package dev.exactrpn;

import static org.junit.jupiter.api.Assertions.*;

import org.junit.jupiter.api.Test;

final class SnapshotTest {
    // Generated by the engine at the published v0.9 tag, not by the new writer.
    @Test
    void version09CalculationRetainsItsRedoAndEntryBoundary() throws Exception {
        TestCalculator calculator =
                TestCalculator.load(
                        java.util.Base64.getDecoder()
                                .decode(
                                        ""));
        assertEquals("3", calculator.entry());
        assertEquals("12", calculator.values().get(0).bigIntegerValue().toString());
        calculator.key("REDO");
        assertEquals("15", calculator.values().get(0).bigIntegerValue().toString());
        calculator.key("UNDO");
        assertEquals("3", calculator.entry());
        assertEquals("12", calculator.values().get(0).bigIntegerValue().toString());
    }

    @Test
    void version09AmbiguousEntryStillRequiresCallerCorrection() throws Exception {
        TestCalculator calculator =
                TestCalculator.load(
                        java.util.Base64.getDecoder()
                                .decode(
                                        ""));
        assertEquals("1,234", calculator.entry());
        assertEquals("Ambiguous", calculator.entryProblem());
        IllegalArgumentException error =
                assertThrows(IllegalArgumentException.class, () -> calculator.key("+"));
        assertEquals(CalculationError.Code.AMBIGUOUS_NUMBER, ((CalculationError) error).code());
        assertEquals("12", calculator.values().get(0).bigIntegerValue().toString());
        assertEquals("1,234", calculator.entry());
    }

    @Test
    void draftSnapshotsRestoreTheLocalEditHistory() throws Exception {
        TestCalculator calculator = new TestCalculator();
        calculator.key("1");
        calculator.key("2");
        calculator.key("3");
        EntryEditor editor = TestCalculator.load(calculator.save()).detachEntryEditor();
        editor.key("UNDO");
        assertEquals("12", editor.entry());
        editor.key("REDO");
        assertEquals("123", editor.entry());
    }

    @Test
    void replacingAnEntryDoesNotNestOrGrowTheArithmeticSection() throws Exception {
        TestCalculator calculator = new TestCalculator();
        calculator.key("π");
        byte[] first = calculator.save();
        EntryEditor entry = new EntryEditor();
        entry.key("7");
        byte[] second = RpnCalculator.saveWithEntry(first, entry);
        byte[] third = RpnCalculator.saveWithEntry(second, entry);
        assertArrayEquals(second, third);
        assertEquals("7", TestCalculator.load(third).entry());
        assertEquals(calculator.values().size(), TestCalculator.load(third).values().size());
    }
}
